import { sql } from 'drizzle-orm'
import { timestamp, uuid } from 'drizzle-orm/pg-core'

/** UTC instants. Due dates use `date()` instead. */
export const timestamptz = () => timestamp({ withTimezone: true, mode: 'date' })

/** UUID v7 primary key generated by Postgres 18 (decision 0012). */
export const id = () => uuid().primaryKey().default(sql`uuidv7()`)

export const timestamps = {
  createdAt: timestamptz().defaultNow().notNull(),
  updatedAt: timestamptz()
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date()),
}
